 * Node constructors for the document tree, and path-string helpers shared by
 * the parser (for error messages) and the keys formatter.
 */

export function tableNode() {
  return { kind: 'table', entries: new Map(), headerLocked: false }
}

export function arrayNode(items = [], isAOT = false) {
  return { kind: 'array', items, isAOT }
}

export function stringNode(value) {
  return { kind: 'string', value }
}

export function integerNode(value) {
  return { kind: 'integer', value }
}

export function floatNode(value) {
  return { kind: 'float', value }
}

export function booleanNode(value) {
  return { kind: 'boolean', value }
}

export function pushKey(path, name) {
  return path === '' ? name : `${path}.${name}`
}

export function pushIndex(path, index) {
  return `${path}[${index}]`
}
"}

