{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3pJJB/src/strings.js","content":"/**
 * Readers for quoted strings, shared by name parsing and value parsing.
 * Each returns the decoded text and the position just past the closing quote.
 */

import { err } from './errors.js'

const ESCAPES = {
  '"': '"',
  '\\': '\\',
  n: '\n',
  t: '\t',
  r: '\r',
  0: '\0',
}

const HEX4 = /^[0-9a-fA-F]{4}$/

export function readBasicStringRaw(line, pos, lineNo) {
  // pos is at the opening '"'.
  let p = pos + 1
  let value = ''
  while (true) {
    if (p >= line.length) throw err(lineNo, 'unterminated string')
    const ch = line[p]
    if (ch === '"') return { value, pos: p + 1 }
    if (ch === '\\') {
      const esc = line[p + 1]
      if (esc === undefined) throw err(lineNo, 'unterminated string')
      if (esc === 'u') {
        const hex = line.slice(p + 2, p + 6)
        if (!HEX4.test(hex)) throw err(lineNo, 'invalid escape \\u')
        value += String.fromCharCode(parseInt(hex, 16))
        p += 6
        continue
      }
      if (Object.prototype.hasOwnProperty.call(ESCAPES, esc)) {
        value += ESCAPES[esc]
        p += 2
        continue
      }
      throw err(lineNo, `invalid escape \\${esc}`)
    }
    value += ch
    p += 1
  }
}

export function readLiteralStringRaw(line, pos, lineNo) {
  // pos is at the opening quote.
  let p = pos + 1
  const start = p
  while (true) {
    if (p >= line.length) throw err(lineNo, 'unterminated string')
    if (line[p] === "'") return { value: line.slice(start, p), pos: p + 1 }
    p += 1
  }
}
"}

