{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3pJJB/src/parser.js","content":"/**
 * The parser: turns the text of a configuration document into the node tree
 * defined in nodes.js, or throws a ParseError.
 */

import { err } from './errors.js'
import { readBasicStringRaw, readLiteralStringRaw } from './strings.js'
import { tableNode, arrayNode, stringNode, integerNode, floatNode, booleanNode, pushKey, pushIndex } from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*(?:(?:\.[0-9]+(?:_[0-9]+)*)(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?|(?:[eE][+-]?[0-9]+(?:_[0-9]+)*))$/

function skipWs(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos += 1
  return pos
}

// Skips whitespace, then reports whether the line has effectively ended:
// either the text ran out or an unquoted comment marker starts here.
function atEnd(line, pos) {
  const p = skipWs(line, pos)
  if (p >= line.length) return { end: true, pos: p }
  if (line[p] === '#' || line[p] === ';') return { end: true, pos: p }
  return { end: false, pos: p }
}

function isBlankOrComment(line) {
  const p = skipWs(line, 0)
  return p >= line.length || line[p] === '#' || line[p] === ';'
}

function parseName(line, pos, lineNo) {
  const ch = line[pos]
  if (ch === '"') return readBasicStringRaw(line, pos, lineNo)
  if (ch === "'") return readLiteralStringRaw(line, pos, lineNo)
  const start = pos
  while (pos < line.length && NAME_CHAR.test(line[pos])) pos += 1
  if (pos === start) throw err(lineNo, 'expected a name')
  return { value: line.slice(start, pos), pos }
}

function parseDottedName(line, pos, lineNo) {
  pos = skipWs(line, pos)
  const first = parseName(line, pos, lineNo)
  const names = [first.value]
  pos = first.pos
  while (true) {
    const save = pos
    const afterWs = skipWs(line, pos)
    if (line[afterWs] === '.') {
      pos = skipWs(line, afterWs + 1)
