{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3pJJB/src/format.js","content":"/**
 * Turns a parsed document tree into either canonical JSON text or a flat
 * `keys` listing.
 */

function cmpCodePoint(a, b) {
  const ai = [...a]
  const bi = [...b]
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i += 1) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(table) {
  return [...table.entries.keys()].sort(cmpCodePoint)
}

function jsonEscape(str) {
  let out = '"'
  for (const ch of str) {
    const code = ch.codePointAt(0)
    if (ch === '"') out += '\\"'
    else if (ch === '\\') out += '\\\\'
    else if (ch === '\n') out += '\\n'
    else if (ch === '\t') out += '\\t'
    else if (ch === '\r') out += '\\r'
    else if (code < 0x20) out += `\\u${code.toString(16).padStart(4, '0')}`
    else out += ch
  }
  return `${out}"`
}

function printValue(node, depth) {
  const pad = '  '.repeat(depth)
  const padIn = '  '.repeat(depth + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => `${padIn}${jsonEscape(k)}: ${printValue(node.entries.get(k), depth + 1)}`)
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => `${padIn}${printValue(it, depth + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return jsonEscape(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return `${printValue(root, 0)}\n`
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) {
      const child = node.entries.get(k)
      const p = path === '' ? k : `${path}.${k}`
      out.push(`${p} ${child.kind}`)
      walkKeys(child, p, out)
    }
  } else if (node.kind === 'array') {
    node.items.forEach((child, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${child.kind}`)
      walkKeys(child, p, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.length ? `${out.join('\n')}\n` : ''
}
"}

